import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_attention(torch::Tensor Q, torch::Tensor K, torch::Tensor V);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>

using namespace cute;

template <int BM_, int BN_, int BK_>
__global__ void attn_kernel(const half* __restrict__ Qg,
                             const half* __restrict__ Kg,
                             const half* __restrict__ Vg,
                             half* __restrict__ Og,
                             int B, int H, int S, int D, float scale)
{
    constexpr int BM = BM_;
    constexpr int BN = BN_;
    constexpr int BK = BK_;

    int bh = blockIdx.y;
    int b = bh / H;
    int h = bh % H;
    int m_tile = blockIdx.x;
    int m_start = m_tile * BM;

    int tx = threadIdx.x; // 0..BN-1
    int ty = threadIdx.y; // 0..BM-1

    size_t bh_off = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Qptr = Qg + bh_off;
    const half* Kptr = Kg + bh_off;
    const half* Vptr = Vg + bh_off;
    half* Optr = Og + bh_off;

    Tensor Qt = make_tensor(make_gmem_ptr(Qptr), make_shape(S, D), make_stride(D, 1));
    Tensor Kt = make_tensor(make_gmem_ptr(Kptr), make_shape(S, D), make_stride(D, 1));
    Tensor Vt = make_tensor(make_gmem_ptr(Vptr), make_shape(S, D), make_stride(D, 1));
    Tensor Ot = make_tensor(make_gmem_ptr(Optr), make_shape(S, D), make_stride(D, 1));

    extern __shared__ unsigned char smem_raw[];
    half* Qs_ptr = reinterpret_cast<half*>(smem_raw);
    half* Ks_ptr = Qs_ptr + BM * BK;
    float* Sc_ptr = reinterpret_cast<float*>(Ks_ptr + BN * BK);

    Tensor Qs = make_tensor(make_smem_ptr(Qs_ptr), make_shape(Int<BM>{}, Int<BK>{}), make_stride(Int<BK>{}, Int<1>{}));
    Tensor Ks = make_tensor(make_smem_ptr(Ks_ptr), make_shape(Int<BN>{}, Int<BK>{}), make_stride(Int<BK>{}, Int<1>{}));
    Tensor Sc = make_tensor(make_smem_ptr(Sc_ptr), make_shape(BM, S), make_stride(S, 1));

    int n_tiles = (S + BN - 1) / BN;
    int k_tiles = (D + BK - 1) / BK;

    // Phase 1: compute Q.K^T * scale into Sc
    for (int nt = 0; nt < n_tiles; ++nt) {
        float acc = 0.f;
        for (int kt = 0; kt < k_tiles; ++kt) {
            int qm = m_start + ty;
            int qk = kt * BK + tx;
            Qs(ty, tx) = (qm < S && qk < D) ? Qt(qm, qk) : __float2half(0.f);

            int kn = nt * BN + ty;
            int kk = kt * BK + tx;
            Ks(ty, tx) = (kn < S && kk < D) ? Kt(kn, kk) : __float2half(0.f);

            __syncthreads();

            float partial = 0.f;
            #pragma unroll
            for (int kk2 = 0; kk2 < BK; ++kk2) {
                partial += __half2float(Qs(ty, kk2)) * __half2float(Ks(tx, kk2));
            }
            acc += partial;
            __syncthreads();
        }
        int n = nt * BN + tx;
        if (n < S) {
            Sc(ty, n) = acc * scale;
        }
    }

    __syncthreads();

    // Phase 2: softmax over each row, parallelized across the warp (BN == warpSize)
    {
        int m = m_start + ty;
        if (m < S) {
            float local_max = -1e30f;
            for (int n = tx; n < S; n += BN) {
                local_max = fmaxf(local_max, Sc(ty, n));
            }
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                local_max = fmaxf(local_max, __shfl_xor_sync(0xffffffff, local_max, offset));
            }
            float local_sum = 0.f;
            for (int n = tx; n < S; n += BN) {
                float e = expf(Sc(ty, n) - local_max);
                Sc(ty, n) = e;
                local_sum += e;
            }
            #pragma unroll
            for (int offset = 16; offset > 0; offset >>= 1) {
                local_sum += __shfl_xor_sync(0xffffffff, local_sum, offset);
            }
            float inv = 1.f / local_sum;
            for (int n = tx; n < S; n += BN) {
                Sc(ty, n) *= inv;
            }
        }
    }
    __syncthreads();
    __syncthreads();

    // Phase 3: O = P @ V
    int d_tiles = (D + BK - 1) / BK;
    for (int dt = 0; dt < d_tiles; ++dt) {
        float acc = 0.f;
        for (int nt = 0; nt < n_tiles; ++nt) {
            int vn = nt * BN + ty;
            int vd = dt * BK + tx;
            Ks(ty, tx) = (vn < S && vd < D) ? Vt(vn, vd) : __float2half(0.f);
            __syncthreads();

            #pragma unroll
            for (int nn = 0; nn < BN; ++nn) {
                int n_global = nt * BN + nn;
                float p = (n_global < S) ? Sc(ty, n_global) : 0.f;
                acc += p * __half2float(Ks(nn, tx));
            }
            __syncthreads();
        }
        int m = m_start + ty;
        int d = dt * BK + tx;
        if (m < S && d < D) {
            Ot(m, d) = __float2half(acc);
        }
    }
}

torch::Tensor cute_attention(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q,K,V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Expect float16 tensors");
    TORCH_CHECK(Q.dim() == 4, "Expect 4D tensors (B,H,S,D)");

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int S = (int)Qc.size(2);
    int D = (int)Qc.size(3);

    auto O = torch::empty_like(Qc);

    constexpr int BM = 32;
    constexpr int BN = 32;
    constexpr int BK = 32;

    float scale = 1.0f / sqrtf((float)D);

    dim3 block(BN, BM);
    dim3 grid((S + BM - 1) / BM, B * H);

    size_t smem_bytes = (size_t)BM * BK * sizeof(half) +
                         (size_t)BN * BK * sizeof(half) +
                         (size_t)BM * S * sizeof(float);

    auto kernel_ptr = attn_kernel<BM, BN, BK>;
    if (smem_bytes > 48 * 1024) {
        cudaFuncSetAttribute(kernel_ptr, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_bytes);
    }

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    kernel_ptr<<<grid, block, smem_bytes, stream>>>(
        reinterpret_cast<const half*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, D, scale);

    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUTE attention kernel launch failed");
    return O;
}
"""

cute_ext = load_inline(
    name="cute_attention_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_attention"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/workspace/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_attention(Q, K, V)

